TWComponent.script:
if(tw.local.odcRequest.requestNature.value == ""+tw.epv.RequestNature.NewRequest)
{
	tw.local.fullPath = tw.local.odcRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.odcRequest.requestNo+"ODC"+"/Issuance";
	tw.local.parentPath = tw.env.FILENET_ROOT_PATH+"/"+ tw.local.odcRequest.CustomerInfo.cif+"/DC Outward/"+tw.local.odcRequest.requestNo+"ODC";
}
if(tw.local.odcRequest.requestNature.value == ""+tw.epv.RequestNature.UpdateRequest)
{
	tw.local.parentPath= tw.env.FILENET_ROOT_PATH+"/"+ tw.local.odcRequest.CustomerInfo.cif+"/DC Outward/"+tw.local.odcRequest.parentRequestNo+"ODC";

	if(tw.local.odcRequest.requestType.value == ""+tw.epv.RequestType.Amendment)
		tw.local.fullPath = tw.local.odcRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.odcRequest.parentRequestNo+"ODC"+"/Amendment "+tw.local.odcRequest.requestNo;
	
	if(tw.local.odcRequest.requestType.value == ""+tw.epv.RequestType.Recreate)
		tw.local.fullPath = tw.local.odcRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.odcRequest.parentRequestNo+"ODC"+"/Recreate "+tw.local.odcRequest.requestNo;
	
	if(tw.local.odcRequest.requestType.value == ""+tw.epv.RequestType.Collection)
		tw.local.fullPath = tw.local.odcRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.odcRequest.parentRequestNo+"ODC"+"/Collection "+tw.local.odcRequest.requestNo;
	
	if(tw.local.odcRequest.requestType.value == ""+tw.epv.RequestType.Closure)
		tw.local.fullPath = tw.local.odcRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.odcRequest.parentRequestNo+"ODC"+"/Closure "+tw.local.odcRequest.requestNo;
	
	if(tw.local.odcRequest.requestType.value == ""+tw.epv.RequestType.Reversal)
		tw.local.fullPath = tw.local.odcRequest.CustomerInfo.cif +"/DC Outward/"+ tw.local.odcRequest.parentRequestNo+"ODC"+"/Reversal "+tw.local.odcRequest.requestNo;
}

